349	.policy__cta { margin-top: clamp(32px,4cqw,48px); display: inline-flex; align-items: center; gap: 16px; background: #12243F; color: #F5F8FC; font-family: Archivo, sans-serif; font-size: 13px; letter-spacing: 0.16em; padding: 20px 34px; transition: background .3s ease, gap .3s ease; }
350	.policy__cta:hover { background: #E8722A; gap: 26px; }
351	
352	/* ============================================
353	   error-page（404.html / support.js非依存の静的ページ）
354	   ============================================ */
355	.error-page { max-width: 375px; margin: 0 auto; background: #F5F8FC; min-height: 100svh; display: flex; flex-direction: column; align-items: flex-start; justify-content: center; gap: 20px; padding: clamp(32px,8cqw,80px); box-shadow: 0 0 80px rgba(18,36,63,0.16); }
356	.error-page__code { margin: 0; font-family: Archivo, sans-serif; font-weight: 400; font-size: clamp(64px,18cqw,120px); line-height: 1; color: #12243F; }
357	.error-page__title { margin: 0; font-size: 18px; font-weight: 500; color: #12243F; }
358	.error-page__message { margin: 0; font-size: 14px; line-height: 2; color: #4A5D78; }
359	.error-page__back { margin-top: 12px; display: inline-flex; align-items: center; gap: 16px; background: #12243F; color: #F5F8FC; font-family: Archivo, sans-serif; font-size: 13px; letter-spacing: 0.16em; padding: 20px 34px; transition: background .3s ease, gap .3s ease; }
360	.error-page__back:hover { background: #E8722A; gap: 26px; }
