1	/* ============================================
2	   共通リセット
3	   ============================================ */
4	html { scroll-behavior: smooth; }
5	@media (prefers-reduced-motion: reduce) { html { scroll-behavior: auto; } * { animation: none !important; } }
6	* { box-sizing: border-box; }
7	body { margin: 0; font-family: "Zen Kaku Gothic New", "Archivo", system-ui, sans-serif; -webkit-font-smoothing: antialiased; }
8	a { color: inherit; text-decoration: none; }
9	
10	/* ページテーマ（body class="page-xxx"） */
11	/* page-portfolio（404）・page-privacy はTOPページと同じ新配色。page-pianist・page-horror は現行デザインを維持（別途リニューアル予定のため変更しない） */
12	body.page-portfolio { background: #EAF6FB; color: #10485F; }
13	body.page-privacy { background: #EAF6FB; color: #10485F; }
14	body.page-pianist { background: #DDE5EF; color: #12243F; }
15	body.page-portfolio a:hover { color: #B57E00; }
16	body.page-privacy a:hover { color: #B57E00; }
17	body.page-pianist a:hover { color: #D2661F; }
18	body.page-portfolio ::selection,
19	body.page-privacy ::selection { background: #FFE79A; color: #10485F; }
20	
21	body.page-horror { background: #07070A; color: #D6D2CB; }
22	body.page-horror a:hover { color: #9B2C22; }
23	
24	/* ============================================
25	   キーフレームアニメーション
26	   ============================================ */
27	@keyframes scrollcue { 0% { transform: translateY(-100%); } 100% { transform: translateY(100%); } }
28	@keyframes fadeup { from { opacity: 0; transform: translateY(24px); } to { opacity: 1; transform: none; } }
29	@keyframes flick { 0%,100% { opacity: .85; } 47% { opacity: .85; } 48% { opacity: .35; } 52% { opacity: .9; } 70% { opacity: .6; } }
30	@keyframes slowfade { from { opacity: 0; } to { opacity: 1; } }
31	@keyframes floatY { 0%,100% { transform: translateY(0); } 50% { transform: translateY(-9px); } }
32	@keyframes floatY2 { 0%,100% { transform: translateY(0); } 50% { transform: translateY(-14px); } }
33	@keyframes sway { 0%,100% { transform: translateX(0); } 50% { transform: translateX(-40px); } }
34	@keyframes nodeGlow { 0%,100% { box-shadow: 0 0 0 0 rgba(255,199,44,0); } 50% { box-shadow: 0 0 0 7px rgba(255,199,44,0.16); } }
35	@keyframes pulseRing { 0% { transform: scale(1); opacity: .55; } 70% { transform: scale(2.1); opacity: 0; } 100% { transform: scale(2.1); opacity: 0; } }
36	
37	/* ============================================
38	   共通ユーティリティ（複数ブロックで使い回すパーツ）
39	   ============================================ */
40	.container { max-width: 1280px; margin: 0 auto; }
41	.sub-container { max-width: 1180px; margin: 0 auto; }
42	.text-block { margin: 0; }
43	
44	.eyebrow { font-family: Jost, sans-serif; font-size: 11px; letter-spacing: 0.26em; color: #B57E00; margin: 0 0 28px; }
45	.eyebrow--tight { margin-bottom: 24px; }
46	
47	.section { position: relative; padding: clamp(56px,8cqw,130px) clamp(20px,6cqw,80px) clamp(64px,9cqw,130px); }
48	.section--first { min-height: 100svh; padding: clamp(104px,13cqw,150px) clamp(20px,6cqw,80px) clamp(64px,8cqw,90px); overflow: hidden; }
49	.section--about { padding-top: clamp(72px,10cqw,150px); padding-bottom: clamp(56px,8cqw,120px); }
50	.section--works { padding-top: clamp(48px,7cqw,120px); }
51	.section--next { overflow: hidden; }
52	.section--contact { padding: clamp(64px,10cqw,160px) clamp(20px,6cqw,80px) clamp(72px,10cqw,160px); }
53	.section__head { display: flex; flex-direction: column; align-items: center; text-align: center; gap: 14px; margin-bottom: clamp(36px,6cqw,80px); }
54	.section__eyebrow { font-family: Jost, sans-serif; font-size: 11px; letter-spacing: 0.26em; color: #B57E00; margin: 0; }
55	.section__heading { margin: 0; font-weight: 500; font-size: clamp(23px,3.6cqw,46px); line-height: 1.55; letter-spacing: -0.01em; color: #0E4257; }
56	.section__intro { text-align: center; }
57	
58	.wave-divider { line-height: 0; position: relative; }
59	.wave-divider--to-dark { background: linear-gradient(180deg,#2A97C4,#0E4257); }
60	.wave-divider__svg { display: block; width: 100%; height: clamp(44px,7cqw,84px); }
61	
62	/* ============================================
63	   shell（各ページ共通の外枠カード）
64	   ============================================ */
65	.shell {
66	  container-type: inline-size;
67	  max-width: 375px;
68	  margin: 0 auto;
69	  min-height: 100svh;
70	  position: relative;
71	  overflow-x: hidden;
72	  display: flex;
73	  flex-direction: column;
