75	  box-shadow: 0 0 80px rgba(18,36,63,0.16);
76	}
77	.shell--muted { background: #F0F5FA; }
78	.shell--dark { background: #0B0B0C; box-shadow: 0 0 80px rgba(0,0,0,0.5); }
79	
80	.skip-link { position: absolute; left: -9999px; top: 0; background: #12243F; color: #F5F8FC; padding: 12px 18px; z-index: 200; }
81	.skip-link:focus { left: 12px; top: 12px; }
82	
83	/* ============================================
84	   top-shell（TOPページ専用の外枠カード。.shellは他ページ共有のため触らずこちらを使う）
85	   ============================================ */
86	.top-shell {
87	  container-type: inline-size;
88	  max-width: 375px;
89	  margin: 0 auto;
90	  min-height: 100svh;
91	  position: relative;
92	  overflow-x: clip;
93	  display: flex;
94	  flex-direction: column;
95	  background: linear-gradient(180deg,#F4FBFE 0%,#EAF7FC 14%,#DCF1F9 34%,#E9F7FC 52%,#DDF2F9 72%,#F1FAFD 100%);
96	  box-shadow: 0 0 90px rgba(16,72,95,0.16);
97	}
