99	/* 背景の曲線スパイン（装飾） */
100	.spine { position: absolute; left: 0; right: 0; top: 92svh; bottom: 120px; z-index: 0; pointer-events: none; }
101	.spine__svg { display: block; width: 100%; height: 100%; overflow: visible; }
102	
103	/* ============================================
104	   hero-nav（TOPページ固定ヘッダー）
105	   ============================================ */
106	.hero-nav__veil {
107	  position: fixed; top: 0; left: 50%; transform: translateX(-50%);
108	  width: min(100%,375px); height: 88px; z-index: 89; pointer-events: none;
109	  backdrop-filter: blur(14px) saturate(150%); -webkit-backdrop-filter: blur(14px) saturate(150%);
110	  background: linear-gradient(180deg,rgba(244,251,254,0.72),rgba(244,251,254,0));
111	  -webkit-mask-image: linear-gradient(180deg,#000 0%,#000 58%,rgba(0,0,0,0) 100%);
112	  mask-image: linear-gradient(180deg,#000 0%,#000 58%,rgba(0,0,0,0) 100%);
113	}
114	.hero-nav {
115	  position: fixed; top: 0; left: 50%; transform: translateX(-50%);
116	  width: min(100%,375px); z-index: 90; display: flex; align-items: center;
117	  justify-content: space-between; padding: 22px clamp(18px,5cqw,48px);
118	  pointer-events: none;
119	}
120	.hero-nav__logo {
121	  pointer-events: auto; font-family: Jost, sans-serif; font-size: 13px; letter-spacing: 0.16em;
122	  color: #0E4257; transition: opacity .3s ease;
123	}
124	.hero-nav.is-open .hero-nav__logo { opacity: 0; pointer-events: none; }
125	.hero-nav__toggle {
126	  pointer-events: auto; width: 44px; height: 44px; display: flex; flex-direction: column;
127	  justify-content: center; align-items: flex-end; gap: 7px; background: none; border: none;
128	  cursor: pointer; padding: 0;
129	}
130	.hero-nav__bar {
131	  display: block; height: 2px; border-radius: 2px; background: #0E4257; width: 18px;
132	  transition: transform .4s cubic-bezier(.2,.7,.2,1), width .4s ease, background .3s ease;
133	}
134	.hero-nav__bar--top { width: 26px; }
135	.hero-nav.is-open .hero-nav__bar { background: #F4FBFE; }
136	.hero-nav.is-open .hero-nav__bar--top { transform: translateY(5px) rotate(14deg); }
137	.hero-nav.is-open .hero-nav__bar--bottom { width: 26px; transform: translateY(-5px) rotate(-14deg); }
138	
139	/* ============================================
140	   flow-rail（スクロール進行レール）
141	   ============================================ */
142	.flow-rail { position: fixed; bottom: 0; left: 50%; transform: translateX(-50%); width: min(100%,375px); height: 3px; z-index: 70; pointer-events: none; }
143	.flow-rail__track { position: absolute; inset: 0; background: rgba(79,195,232,0.22); }
144	.flow-rail__fill { position: absolute; left: 0; bottom: 0; height: 3px; width: 0%; background: linear-gradient(90deg,#4FC3E8,#FFC72C); border-radius: 3px; }
145	.flow-rail__rider { position: absolute; left: 17px; bottom: 7px; transform: translate(-50%,0); width: 30px; height: 30px; border-radius: 50%; background: #FFFFFF; box-shadow: 0 4px 16px rgba(16,72,95,0.22); display: flex; align-items: center; justify-content: center; }
146	.flow-rail__pulse { position: absolute; inset: 0; border-radius: 50%; background: rgba(255,199,44,0.45); animation: pulseRing 2.8s ease-out infinite; }
147	.flow-rail__icon { position: relative; width: 17px; height: 17px; }
148	
149	/* ============================================
150	   page-header（下層ページの戻るリンクヘッダー）
151	   ============================================ */
152	.page-header { padding: 24px clamp(20px,6cqw,80px); display: flex; justify-content: space-between; align-items: center; font-family: Archivo, sans-serif; font-size: 12px; letter-spacing: 0.16em; }
153	.page-header--dark { color: #8A8580; }
