432	.horror-gate__message { margin: clamp(28px,5cqw,52px) 0 0; font-family: Archivo, sans-serif; font-size: clamp(18px,3.2cqw,40px); line-height: 1.7; letter-spacing: 0.08em; color: #CFC9C1; }
433	.horror-gate__enter { margin-top: clamp(40px,6cqw,72px); background: none; border: 1px solid #3A3736; color: #D6D2CB; font-family: Archivo, sans-serif; font-size: 13px; letter-spacing: 0.3em; padding: 18px 44px; cursor: pointer; transition: background .4s ease, border-color .4s ease, letter-spacing .4s ease; }
434	.horror-gate__enter:hover { background: #9B2C22; border-color: #9B2C22; letter-spacing: 0.42em; }
435	.horror-gate__back { margin-top: 28px; font-family: Archivo, sans-serif; font-size: 11px; letter-spacing: 0.2em; color: #5A5652; }
436	
437	.horror-hero { padding: clamp(60px,10cqw,150px) clamp(20px,6cqw,80px) clamp(50px,7cqw,110px); border-bottom: 1px solid #1E1D1D; }
438	.horror-hero__title { margin: 0; font-family: Archivo, sans-serif; font-weight: 400; font-size: clamp(52px,14cqw,190px); line-height: 0.9; letter-spacing: -0.03em; color: #EDE9E3; }
439	.horror-hero__desc { margin: clamp(28px,4cqw,52px) 0 0; font-size: 15px; line-height: 2.2; color: #9A948C; max-width: 44ch; }
440	
441	.horror-archive { padding: clamp(50px,7cqw,110px) clamp(20px,6cqw,80px); }
442	.horror-archive__eyebrow { font-family: Archivo, sans-serif; font-size: 11px; letter-spacing: 0.26em; color: #5A5652; margin: 0 0 clamp(28px,4cqw,48px); }
443	.horror-archive__grid { list-style: none; margin: 0; padding: 0; display: grid; grid-template-columns: repeat(auto-fit,minmax(260px,1fr)); gap: clamp(24px,3cqw,44px); }
444	.horror-archive__thumb { aspect-ratio: 16/10; background-image: repeating-linear-gradient(135deg,#141414 0 10px,#101010 10px 20px); border: 1px solid #1E1D1D; display: flex; align-items: center; justify-content: center; transition: border-color .4s ease; }
445	.horror-archive__thumb:hover { border-color: #9B2C22; }
446	.horror-archive__thumb-label { font-family: ui-monospace,Menlo,monospace; font-size: 11px; letter-spacing: 0.16em; color: #5A5652; }
447	.horror-archive__no { margin: 16px 0 0; font-family: Archivo, sans-serif; font-size: 11px; letter-spacing: 0.2em; color: #5A5652; }
448	.horror-archive__title { margin: 8px 0 0; font-size: 15px; color: #C7C2BB; }
449	
450	/* ============================================
451	   policy（PRIVACYページ）
452	   ============================================ */
453	.policy { padding: clamp(40px,8cqw,110px) clamp(20px,6cqw,80px) clamp(60px,8cqw,120px); }
454	.policy__eyebrow { margin: 0; font-family: Jost, sans-serif; font-size: 11px; letter-spacing: 0.26em; color: #B57E00; }
455	.policy__title { margin: 20px 0 0; font-weight: 500; font-size: clamp(24px,4.4cqw,44px); line-height: 1.5; letter-spacing: -0.01em; color: #0E4257; }
456	.policy__intro { margin: 24px 0 0; font-size: 14px; line-height: 2.1; color: #2E7793; }
457	.policy__note { font-family: Jost, sans-serif; font-size: 12px; letter-spacing: 0.1em; color: #4E9DBC; }
458	.policy-list { list-style: none; margin: clamp(40px,6cqw,72px) 0 0; padding: 0; display: grid; gap: clamp(32px,4cqw,52px); }
459	.policy-list__item { border-top: 1px solid rgba(79,195,232,0.28); padding-top: 24px; }
460	.policy-list__no { margin: 0; font-family: Jost, sans-serif; font-size: 11px; letter-spacing: 0.2em; color: #4E9DBC; }
461	.policy-list__heading { margin: 12px 0 0; font-weight: 500; font-size: 18px; color: #0E4257; }
462	.policy-list__body { margin: 14px 0 0; font-size: 14px; line-height: 2.1; color: #2E7793; }
463	.policy__updated { margin: clamp(40px,5cqw,64px) 0 0; font-family: Jost, sans-serif; font-size: 11px; letter-spacing: 0.16em; color: #4E9DBC; }
464	.policy__cta { margin-top: clamp(32px,4cqw,48px); display: inline-flex; align-items: center; gap: 16px; background: linear-gradient(120deg,#FFC72C,#FFE07A); color: #0E4257; font-weight: 700; font-family: Jost, sans-serif; font-size: 13px; letter-spacing: 0.16em; padding: 20px 34px; border-radius: 999px; transition: gap .3s ease, box-shadow .3s ease; box-shadow: 0 14px 28px rgba(255,199,44,0.26); }
465	.policy__cta:hover { gap: 26px; box-shadow: 0 18px 34px rgba(255,199,44,0.34); }
466	
467	/* ============================================
468	   error-page（404.html / support.js非依存の静的ページ）
469	   ============================================ */
470	.error-page { max-width: 375px; margin: 0 auto; background: #F4FBFE; min-height: 100svh; display: flex; flex-direction: column; align-items: flex-start; justify-content: center; gap: 20px; padding: clamp(32px,8cqw,80px); box-shadow: 0 0 90px rgba(16,72,95,0.16); }
471	.error-page__code { margin: 0; font-family: Jost, sans-serif; font-weight: 400; font-size: clamp(64px,18cqw,120px); line-height: 1; color: #0E4257; }
472	.error-page__title { margin: 0; font-size: 18px; font-weight: 500; color: #0E4257; }
473	.error-page__message { margin: 0; font-size: 14px; line-height: 2; color: #2E7793; }
474	.error-page__back { margin-top: 12px; display: inline-flex; align-items: center; gap: 16px; background: linear-gradient(120deg,#FFC72C,#FFE07A); color: #0E4257; font-weight: 700; font-family: Jost, sans-serif; font-size: 13px; letter-spacing: 0.16em; padding: 20px 34px; border-radius: 999px; transition: gap .3s ease, box-shadow .3s ease; box-shadow: 0 14px 28px rgba(255,199,44,0.26); }
475	.error-page__back:hover { gap: 26px; box-shadow: 0 18px 34px rgba(255,199,44,0.34); }
